+  static_assert(kHistogramBins % BlockSize == 0);
+  using BlockScan = cub::BlockScan<uint32_t, BlockSize>;
+  struct ExactSmem {
+    uint32_t histogram[kHistogramBins];
+    typename BlockScan::TempStorage scan;
+    uint32_t prefix;
+    uint32_t remaining;
+    uint32_t output_counter;
+  };
